// One row per organic result, with your own domain flagged, then compared
// against the last snapshot already in the sheet so the row says which way it
// moved instead of just where it sits today.
const cfg = $('Set the keywords to track').first().json;
const domain = String(cfg.yourDomain || '').trim().toLowerCase().replace(/^www\./, '');
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

// Match on hostname so a path or a www prefix does not break the flag.
// Parsed with a regex rather than new URL(), which is not available in the
// n8n Code sandbox and fails silently inside a try/catch.
const hostOf = (u) => {
  const m = String(u || '').match(/^https?:\/\/([^/?#]+)/i);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
};

// The sheet holds every week that has ever run, so reduce it to the most recent
// snapshot that is not today's, keyed by keyword and URL. Empty on the first
// run, and the node is set to carry on if the tab does not exist yet.
let history = [];
try {
  history = $('Read the rank history').all().map((i) => i.json);
} catch (e) {
  history = [];
}

const previous = {};
for (const h of history) {
  const week = String(h['Week of'] || '');
  const rank = Number(h.Rank);
  if (!week || week >= weekOf || !isFinite(rank)) continue;
  const key = `${h.Keyword}||${h.URL}`;
  if (!previous[key] || week > previous[key].week) {
    previous[key] = { week, rank };
  }
}

return $input.all().map((item) => {
  const r = item.json;
  const host = hostOf(r.url);
  const mine = domain !== '' && (host === domain || host.endsWith('.' + domain));
  const rank = Number(r.position);
  const prev = previous[`${r.query || ''}||${r.url || ''}`];

  // Rank counts upward while position improves downward, so last week minus
  // this week is positive when a result has climbed.
  const movement = prev && isFinite(rank) ? prev.rank - rank : '';
  let status = 'New';
  if (prev && isFinite(rank)) {
    status = rank < prev.rank ? 'Up' : rank > prev.rank ? 'Down' : 'Flat';
  }

  return {
    json: {
      'Week of': weekOf,
      Keyword: r.query || '',
      Page: r.page ?? '',
      Rank: r.position ?? '',
      'Last week': prev ? prev.rank : '',
      Movement: movement,
      Status: status,
      'Is your site': mine ? 'YES' : '',
      Title: clip(r.title, 180),
      Domain: host,
      Snippet: clip(r.snippet, 300),
      URL: r.url || '',
    },
  };
});
